mapper.select:
select csic.id, csic.update_time updateTime, csic.sku_id skuId, csic.sku_no, csic.country, csic.shop_id shopId, csic.platform, csic.sales_qty_json, csic.avg_sales_qty_json, csic.month_sales_estimate_qty_json, csic.month_real_sales_qty_json, csic.cfg_rule_calc_id, csic.r2_score as r2Score, csic.mape_score as mapeScore from calc_sales_info_dim csic where ${params.sqlMap.default} and csic.is_deleted = FALSE and csic.cfg_rule_calc_id = #{params.cfgRuleCalcId} order by
${item.field} ${item.sort}
csic.update_time desc
